import{_ as l,K as r,a as o,c as s,ac as t,b as i,q as n}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"排球规则 · 人数、场地与器材至自由人：能替后排，但有专门限制","description":"以 FIVB 2025—2028 室内六人制规则理解排球计分、轮转、攻防、自由人与常见犯规","frontmatter":{"title":"排球规则 · 人数、场地与器材至自由人：能替后排，但有专门限制","description":"以 FIVB 2025—2028 室内六人制规则理解排球计分、轮转、攻防、自由人与常见犯规","splitFrom":"life/personal/sports/volleyball-rules.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"排球规则","summary":"以 FIVB 2025—2028 室内六人制规则理解排球计分、轮转、攻防、自由人与常见犯规","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"排球规则","link":"/life/personal/sports/volleyball-rules"},"next":{"text":"排球规则 · 常见犯规与判例至官方资料与阅读范围","link":"/life/personal/sports/volleyball-rules-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"排球规则","link":"/life/personal/sports/volleyball-rules"},"next":{"text":"排球规则 · 常见犯规与判例至官方资料与阅读范围","link":"/life/personal/sports/volleyball-rules-part-02"}},"headers":[],"relativePath":"life/personal/sports/volleyball-rules-part-01.md","filePath":"life/personal/sports/volleyball-rules-part-01.md"}'),p={name:"life/personal/sports/volleyball-rules-part-01.md"};function d(h,e,c,u,b,g){const a=r("ArticleImage");return o(),s("div",null,[e[0]||(e[0]=t('<h1 id="排球规则-·-人数、场地与器材至自由人-能替后排-但有专门限制" tabindex="-1">排球规则 · 人数、场地与器材至自由人：能替后排，但有专门限制 <a class="header-anchor" href="#排球规则-·-人数、场地与器材至自由人-能替后排-但有专门限制" aria-label="Permalink to &quot;排球规则 · 人数、场地与器材至自由人：能替后排，但有专门限制&quot;">​</a></h1><p><a href="/life/personal/sports/volleyball-rules">返回分篇目录</a></p><p>排球由两队隔网对抗，目标是让球落在对方场内，或使对方无法合法回球。<strong>每个回合都有一方得分；接发球队赢得回合，还会获得发球权并顺时针轮转一位。</strong></p><p>本文采用 FIVB《Official Volleyball Rules 2025–2028》，适用于室内六人制，自 2025 年 1 月 1 日之后开始的比赛实施。沙滩排球、气排球、校园简化比赛和个别赛事试行条款，不直接套用本文。</p><h2 id="排球规则" tabindex="-1">排球规则 <a class="header-anchor" href="#排球规则" aria-label="Permalink to &quot;排球规则 {#排球规则}&quot;">​</a></h2><p>排球由两队隔网对抗，目标是让球落在对方场内，或使对方无法合法回球。<strong>每个回合都有一方得分；接发球队赢得回合，还会获得发球权并顺时针轮转一位。</strong></p><p>本文采用 FIVB《Official Volleyball Rules 2025–2028》，适用于室内六人制，自 2025 年 1 月 1 日之后开始的比赛实施。沙滩排球、气排球、校园简化比赛和个别赛事试行条款，不直接套用本文。</p><h2 id="人数、场地与器材" tabindex="-1">人数、场地与器材 <a class="header-anchor" href="#人数、场地与器材" aria-label="Permalink to &quot;人数、场地与器材 {#人数、场地与器材}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>标准规定</th></tr></thead><tbody><tr><td>场上人数</td><td>每队始终有 6 名队员</td></tr><tr><td>场地</td><td>长 18 米、宽 9 米，中线分成两个 9 米见方的半场</td></tr><tr><td>边线与端线</td><td>线宽 5 厘米，均包含在场区内；球落在线上算界内</td></tr><tr><td>进攻线</td><td>距中线轴线 3 米，用于区分前区与后区及部分进攻限制</td></tr><tr><td>球网高度</td><td>成年男子 2.43 米，成年女子 2.24 米；青少年等另依赛事规定</td></tr><tr><td>发球区</td><td>端线后宽 9 米的区域；发球击球或起跳时不得踩端线及区外地面</td></tr><tr><td>比赛用球</td><td>周长 65—67 厘米，重量 260—280 克</td></tr></tbody></table><p>“主攻、副攻、二传、接应”是战术分工；“前排、后排”是轮转位置带来的规则身份。主攻轮到后排，同样受后排进攻和拦网限制。</p><h2 id="看图认位置-前排不是永远站在网前的人" tabindex="-1">看图认位置：前排不是永远站在网前的人 <a class="header-anchor" href="#看图认位置-前排不是永远站在网前的人" aria-label="Permalink to &quot;看图认位置：前排不是永远站在网前的人 {#看图认位置-前排不是永远站在网前的人}&quot;">​</a></h2>',11)),i("p",null,[n(a,{src:"/images/sports/volleyball-court.svg",alt:"六人排球场比例图：进攻线、前后排位置及顺时针轮转"})]),e[1]||(e[1]=t('<p><em>图：场区按 18 × 9 米绘制，进攻线距中线 3 米。下方是本队，从底线朝网看，前排为 4、3、2，后排为 5、6、1。数字代表轮转位置，队员无需始终站在这些点上。</em></p><p>轮转像把六个人依次挪到下一个位置：原 2 号位来到 1 号位发球，原 1 号位到 6 号位，依此继续。发球后队员跑去接应，不会改变该回合的前后排身份。看比赛时先记“这一轮谁是后排”，才看他实际跑到了哪里。</p><h2 id="计分和赛制" tabindex="-1">计分和赛制 <a class="header-anchor" href="#计分和赛制" aria-label="Permalink to &quot;计分和赛制 {#计分和赛制}&quot;">​</a></h2><p>正式比赛采用五局三胜。前四局每局先得 <strong>25 分且领先至少 2 分</strong>的一方获胜；若打到第五局，先得 <strong>15 分且领先至少 2 分</strong>的一方获胜。</p><p>24∶24 后须继续打到 26∶24、27∶25 等；决胜局 14∶14 后也必须净胜 2 分。标准规则没有“到 30 分必须结束”的封顶规定。</p><p>发球队赢回合，得 1 分，由原发球队员继续发球；接发球队赢回合，得 1 分并取得发球权，先轮转再发球。决胜局领先一方达到 8 分时交换场区，轮转位置保持不变。</p><p>双方同一时刻犯规属于双方犯规，通常重新进行该回合。先后发生的犯规一般处罚先发生的一次，但发球犯规与接发球位置错误有专门的先后判定，不能一概以球最终落点决定。</p><h2 id="一次比赛和一个回合怎样开始" tabindex="-1">一次比赛和一个回合怎样开始 <a class="header-anchor" href="#一次比赛和一个回合怎样开始" aria-label="Permalink to &quot;一次比赛和一个回合怎样开始 {#一次比赛和一个回合怎样开始}&quot;">​</a></h2><p>赛前抽签决定首局发球权或场区选择，教练提交每局首发阵容及轮转顺序。裁判核对站位后开始比赛。决胜局重新抽签，其余局的首次发球由上一局未首先发球的一方执行。</p><p>第一裁判鸣哨允许发球后，发球队员须在 <strong>8 秒内</strong>击球，只允许一次抛球或放球。发球在击球时开始，接下来通过接发球、组织、进攻、拦网和防守展开。并非一定要完成“垫、传、扣”三次；一次或两次合法击球直接过网也可以。</p><p>每队每局通常最多请求 2 次暂停和 6 次普通换人；普通暂停为 30 秒。先发队员一局可被替换出场一次、再回场一次，且回到原轮转位置；替补只能由其替下的那名先发队员换回。受伤例外换人、赛事特殊中断及自由人替换另有规定。</p><h2 id="轮转与站位-先分清发球队和接发球队" tabindex="-1">轮转与站位：先分清发球队和接发球队 <a class="header-anchor" href="#轮转与站位-先分清发球队和接发球队" aria-label="Permalink to &quot;轮转与站位：先分清发球队和接发球队 {#轮转与站位-先分清发球队和接发球队}&quot;">​</a></h2><p>从本方底线面向球网，六个位置如下。号码表示轮转位置，不表示球衣号码。</p><table tabindex="0"><thead><tr><th>左侧</th><th>中间</th><th>右侧</th></tr></thead><tbody><tr><td>4 号位：前排左</td><td>3 号位：前排中</td><td>2 号位：前排右</td></tr><tr><td>5 号位：后排左</td><td>6 号位：后排中</td><td>1 号位：后排右，轮到此位发球</td></tr></tbody></table><p>获得发球权时，按 <strong>2 → 1 → 6 → 5 → 4 → 3 → 2</strong> 顺时针轮转。已经在发球的一方连续得分，不需要每分都轮转。</p><h3 id="_2025—2028-版的关键区别" tabindex="-1">2025—2028 版的关键区别 <a class="header-anchor" href="#_2025—2028-版的关键区别" aria-label="Permalink to &quot;2025—2028 版的关键区别 {#_2025—2028-版的关键区别}&quot;">​</a></h3><p>在发球队员击球瞬间，除发球队员外，两队队员都须在本方场内，但相对位置要求不同：</p><ul><li><strong>接发球队</strong>必须符合轮转顺序的前后、左右关系。根据脚与地面的接触位置判断，并不是要求站在六个固定格子中央；同线及部分脚的位置依第 7.4.3 条判定。</li><li><strong>发球队</strong>队员可以自由选择相对站位，不再照搬接发球队的重叠限制。但发球顺序和前、后排身份不变，不能因此让后排队员合法完成拦网。</li><li>发球击出后，两队都可以移动到战术需要的位置；移动不改变本回合的前、后排身份。</li></ul><p>例如接发球队的二传可以提前靠近组织位置，但击球瞬间仍须满足相对站位。发球队的后排二传可以靠近网前站立，却仍然受后排拦网和进攻限制。错误的人发球属于轮转错误，不会因为队员站得整齐而变合法。</p><h2 id="三次击球、连击和持球" tabindex="-1">三次击球、连击和持球 <a class="header-anchor" href="#三次击球、连击和持球" aria-label="Permalink to &quot;三次击球、连击和持球 {#三次击球、连击和持球}&quot;">​</a></h2><p>每队最多击球 <strong>3 次</strong>将球送回对面，<strong>拦网触球不计入这 3 次</strong>。拦网后，刚参与拦网的队员可以继续进行本队第一次击球。</p><p>球可以接触身体任何部位，包括脚，但不能接住、托住或抛出。一般不能由同一队员连续击球两次；两个常见例外是：一次拦网动作中的连续触球，以及本队第一次击球时，同一动作中球先后触及身体不同部位。</p><p>因此，接发球在一次救球动作中先碰手臂再碰身体，不一定连击；二传的传球也不能只凭球旋转判断连击，需观察是否发生不被规则允许的先后接触。将球明显托住再推出，属于持球问题。</p><p>两名队友同时触球，除拦网外通常计作两次击球。第三次触球后仍未合法送往对方，再触球就是四次击球犯规。</p><h2 id="发球、进攻与拦网" tabindex="-1">发球、进攻与拦网 <a class="header-anchor" href="#发球、进攻与拦网" aria-label="Permalink to &quot;发球、进攻与拦网 {#发球、进攻与拦网}&quot;">​</a></h2><h3 id="发球" tabindex="-1">发球 <a class="header-anchor" href="#发球" aria-label="Permalink to &quot;发球 {#发球}&quot;">​</a></h3><p>发球必须按轮转顺序进行，击球或起跳时站在合法发球区内；球击出后可以落入场内。发球触网后从标志杆之间合法过网，比赛继续，不重发。球触及标志杆、从其外侧过网或落在界外，为发球失误。</p><p>发球队不得通过挥臂、跳跃、移动或集体站位，遮挡对手观察发球击球和飞行路线。2025—2028 版第 12.5.3 条还规定，发球队队员在发球期间至球越网前，不得将双手举过头顶。</p><h3 id="后排进攻" tabindex="-1">后排进攻 <a class="header-anchor" href="#后排进攻" aria-label="Permalink to &quot;后排进攻 {#后排进攻}&quot;">​</a></h3><p>后排队员可以在后区起跳，击打完全高于网顶的球，完成进攻；起跳时脚不得踩到或越过进攻线，击球后可以落在前区。</p><p>若从前区起跳或站在前区，后排队员不能在球整体高于网顶时完成进攻性击球。若触球时球并未整体高于网顶，则不能仅凭“后排人在网前把球送过网”判犯规。</p><h3 id="拦网" tabindex="-1">拦网 <a class="header-anchor" href="#拦网" aria-label="Permalink to &quot;拦网 {#拦网}&quot;">​</a></h3><p>只有前排队员可以完成拦网。拦网手可以在符合条件时伸过球网，但不得在对方进攻性击球之前或同时，干扰对方处理球；拦对方发球属于犯规。</p><p>对方发球飞来时，如果球处于本方前区且整体高于网顶，不能直接完成进攻性击球。接发球不能用网前直接扣杀或拦网来绕过这一限制。</p><h2 id="自由人-能替后排-但有专门限制" tabindex="-1">自由人：能替后排，但有专门限制 <a class="header-anchor" href="#自由人-能替后排-但有专门限制" aria-label="Permalink to &quot;自由人：能替后排，但有专门限制 {#自由人-能替后排-但有专门限制}&quot;">​</a></h2><p>自由人通常穿与队友明显不同颜色的球衣，主要负责接发球和后排防守。同一时刻只能有一名自由人在场上，可以替换任意后排位置队员。</p><p>自由人替换不计入每局 6 次普通换人，次数不限，但通常两次替换之间须有一个完整回合，并在死球且允许发球哨声之前按规定区域完成。它不是可在回合进行中随意换人的特权。</p><p>FIVB 室内规则对自由人的主要限制是：</p><ol><li><strong>不得发球、拦网或尝试拦网</strong>。不能将其他联赛允许自由人发球的做法套用到本文。</li><li>无论在场内还是无障碍区，都不能在球整体高于网顶时完成进攻性击球。</li><li>自由人在前区及其延长区域，以双手手指作上手传球后，队友不能在球整体高于网顶时完成进攻性击球。</li></ol><p>第三条不意味着“自由人不能到前区传球”。自由人可以这样传，限制落在随后队友的进攻上；若自由人从后区作相同传球，或在前区用垫球处理，便不触发这一特定限制，但其他规则仍适用。</p>',40))])}const _=l(p,[["render",d]]);export{m as __pageData,_ as default};
